   233→    pub fn block_by_number(&self, number: u64) -> Option<Block<E>> {
   234→        // Get the latest canonical head block
   235→        let mut latest_block = self.latest_block()?;
   236→        loop {
   237→            let block_number = latest_block.block_number();
   238→            if block_number < number {
   239→                return None;
   240→            }
   241→            if block_number == number {
   242→                return Some(latest_block);
   243→            }
   244→            latest_block = self.block_by_hash(latest_block.parent_hash())?;
   245→        }
   246→    }
