   248→    pub fn get_fork_at_timestamp(&self, timestamp: u64) -> ForkName {
   249→        let forks = [
   250→            (self.amsterdam_time, ForkName::Gloas),
   251→            (self.osaka_time, ForkName::Fulu),
   252→            (self.prague_time, ForkName::Electra),
   253→            (self.cancun_time, ForkName::Deneb),
   254→            (self.shanghai_time, ForkName::Capella),
   255→        ];
   256→
   257→        for (fork_time, fork_name) in forks {
   258→            if let Some(time) = fork_time
   259→                && timestamp >= time
   260→            {
   261→                return fork_name;
   262→            }
   263→        }
   264→
   265→        ForkName::Bellatrix
   266→    }
