   592→    pub fn build_new_execution_payload(
   593→        &mut self,
   594→        head_block_hash: ExecutionBlockHash,
   595→        parent: &Block<E>,
   596→        id: PayloadId,
   597→        attributes: &PayloadAttributes,
   598→    ) -> Result<ExecutionPayload<E>, String> {
   599→        let mut execution_payload = match attributes {
   600→            PayloadAttributes::V1(pa) => ExecutionPayload::Bellatrix(ExecutionPayloadBellatrix {
   601→                parent_hash: head_block_hash,
   602→                fee_recipient: pa.suggested_fee_recipient,
   603→                receipts_root: Hash256::repeat_byte(42),
   604→                state_root: Hash256::repeat_byte(43),
   605→                logs_bloom: vec![0; 256].into(),
   606→                prev_randao: pa.prev_randao,
   607→                block_number: parent.block_number() + 1,
   608→                gas_limit: DEFAULT_GAS_LIMIT,
   609→                gas_used: GAS_USED,
   610→                timestamp: pa.timestamp,
   611→                extra_data: mock_el_extra_data::<E>(),
   612→                base_fee_per_gas: Uint256::from(1u64),
   613→                block_hash: ExecutionBlockHash::zero(),
   614→                transactions: vec![].into(),
   615→            }),
   616→            PayloadAttributes::V2(pa) => match self.get_fork_at_timestamp(pa.timestamp) {
   617→                ForkName::Bellatrix => ExecutionPayload::Bellatrix(ExecutionPayloadBellatrix {
   618→                    parent_hash: head_block_hash,
   619→                    fee_recipient: pa.suggested_fee_recipient,
   620→                    receipts_root: Hash256::repeat_byte(42),
   621→                    state_root: Hash256::repeat_byte(43),
   622→                    logs_bloom: vec![0; 256].into(),
   623→                    prev_randao: pa.prev_randao,
   624→                    block_number: parent.block_number() + 1,
   625→                    gas_limit: DEFAULT_GAS_LIMIT,
   626→                    gas_used: GAS_USED,
   627→                    timestamp: pa.timestamp,
   628→                    extra_data: mock_el_extra_data::<E>(),
   629→                    base_fee_per_gas: Uint256::from(1u64),
   630→                    block_hash: ExecutionBlockHash::zero(),
   631→                    transactions: vec![].into(),
   632→                }),
   633→                ForkName::Capella => ExecutionPayload::Capella(ExecutionPayloadCapella {
   634→                    parent_hash: head_block_hash,
   635→                    fee_recipient: pa.suggested_fee_recipient,
   636→                    receipts_root: Hash256::repeat_byte(42),
   637→                    state_root: Hash256::repeat_byte(43),
   638→                    logs_bloom: vec![0; 256].into(),
   639→                    prev_randao: pa.prev_randao,
   640→                    block_number: parent.block_number() + 1,
   641→                    gas_limit: DEFAULT_GAS_LIMIT,
   642→                    gas_used: GAS_USED,
   643→                    timestamp: pa.timestamp,
   644→                    extra_data: mock_el_extra_data::<E>(),
   645→                    base_fee_per_gas: Uint256::from(1u64),
   646→                    block_hash: ExecutionBlockHash::zero(),
   647→                    transactions: vec![].into(),
   648→                    withdrawals: pa.withdrawals.clone().into(),
   649→                }),
   650→                _ => unreachable!(),
   651→            },
   652→            PayloadAttributes::V3(pa) => match self.get_fork_at_timestamp(pa.timestamp) {
   653→                ForkName::Deneb => ExecutionPayload::Deneb(ExecutionPayloadDeneb {
   654→                    parent_hash: head_block_hash,
   655→                    fee_recipient: pa.suggested_fee_recipient,
   656→                    receipts_root: Hash256::repeat_byte(42),
   657→                    state_root: Hash256::repeat_byte(43),
   658→                    logs_bloom: vec![0; 256].into(),
   659→                    prev_randao: pa.prev_randao,
   660→                    block_number: parent.block_number() + 1,
   661→                    gas_limit: DEFAULT_GAS_LIMIT,
   662→                    gas_used: GAS_USED,
   663→                    timestamp: pa.timestamp,
   664→                    extra_data: mock_el_extra_data::<E>(),
   665→                    base_fee_per_gas: Uint256::from(1u64),
   666→                    block_hash: ExecutionBlockHash::zero(),
   667→                    transactions: vec![].into(),
   668→                    withdrawals: pa.withdrawals.clone().into(),
   669→                    blob_gas_used: 0,
   670→                    excess_blob_gas: 0,
   671→                }),
   672→                ForkName::Electra => ExecutionPayload::Electra(ExecutionPayloadElectra {
   673→                    parent_hash: head_block_hash,
   674→                    fee_recipient: pa.suggested_fee_recipient,
   675→                    receipts_root: Hash256::repeat_byte(42),
   676→                    state_root: Hash256::repeat_byte(43),
   677→                    logs_bloom: vec![0; 256].into(),
   678→                    prev_randao: pa.prev_randao,
   679→                    block_number: parent.block_number() + 1,
   680→                    gas_limit: DEFAULT_GAS_LIMIT,
   681→                    gas_used: GAS_USED,
   682→                    timestamp: pa.timestamp,
   683→                    extra_data: mock_el_extra_data::<E>(),
   684→                    base_fee_per_gas: Uint256::from(1u64),
   685→                    block_hash: ExecutionBlockHash::zero(),
   686→                    transactions: vec![].into(),
   687→                    withdrawals: pa.withdrawals.clone().into(),
   688→                    blob_gas_used: 0,
   689→                    excess_blob_gas: 0,
   690→                }),
   691→                ForkName::Fulu => ExecutionPayload::Fulu(ExecutionPayloadFulu {
   692→                    parent_hash: head_block_hash,
   693→                    fee_recipient: pa.suggested_fee_recipient,
   694→                    receipts_root: Hash256::repeat_byte(42),
   695→                    state_root: Hash256::repeat_byte(43),
   696→                    logs_bloom: vec![0; 256].into(),
   697→                    prev_randao: pa.prev_randao,
   698→                    block_number: parent.block_number() + 1,
   699→                    gas_limit: DEFAULT_GAS_LIMIT,
   700→                    gas_used: GAS_USED,
   701→                    timestamp: pa.timestamp,
   702→                    extra_data: "block gen was here".as_bytes().to_vec().into(),
   703→                    base_fee_per_gas: Uint256::from(1u64),
   704→                    block_hash: ExecutionBlockHash::zero(),
   705→                    transactions: vec![].into(),
   706→                    withdrawals: pa.withdrawals.clone().into(),
   707→                    blob_gas_used: 0,
   708→                    excess_blob_gas: 0,
   709→                }),
   710→                ForkName::Gloas => ExecutionPayload::Gloas(ExecutionPayloadGloas {
   711→                    parent_hash: head_block_hash,
   712→                    fee_recipient: pa.suggested_fee_recipient,
   713→                    receipts_root: Hash256::repeat_byte(42),
   714→                    state_root: Hash256::repeat_byte(43),
   715→                    logs_bloom: vec![0; 256].into(),
   716→                    prev_randao: pa.prev_randao,
   717→                    block_number: parent.block_number() + 1,
   718→                    gas_limit: DEFAULT_GAS_LIMIT,
   719→                    gas_used: GAS_USED,
   720→                    timestamp: pa.timestamp,
   721→                    extra_data: "block gen was here".as_bytes().to_vec().into(),
   722→                    base_fee_per_gas: Uint256::from(1u64),
   723→                    block_hash: ExecutionBlockHash::zero(),
   724→                    transactions: vec![].into(),
   725→                    withdrawals: pa.withdrawals.clone().into(),
   726→                    blob_gas_used: 0,
   727→                    excess_blob_gas: 0,
   728→                }),
   729→                _ => unreachable!(),
   730→            },
   731→        };
   732→
   733→        let fork_name = execution_payload.fork_name();
   734→        if fork_name.deneb_enabled() {
   735→            // get random number between 0 and Max Blobs
   736→            let mut rng = self.rng.lock();
   737→            // TODO(EIP-7892): see FIXME below
   738→            // FIXME: this will break with BPO forks. This function needs to calculate the epoch based on block timestamp..
   739→            let max_blobs = self.spec.max_blobs_per_block_within_fork(fork_name) as usize;
   740→            let num_blobs = rng.random_range(self.min_blobs_count..=max_blobs);
   741→            let (bundle, transactions) = generate_blobs(num_blobs, fork_name)?;
   742→            for tx in Vec::from(transactions) {
   743→                execution_payload
   744→                    .transactions_mut()
   745→                    .push(tx)
   746→                    .map_err(|_| "transactions are full".to_string())?;
   747→            }
   748→            self.blobs_bundles.insert(id, bundle);
   749→        }
   750→
   751→        *execution_payload.block_hash_mut() =
   752→            ExecutionBlockHash::from_root(execution_payload.tree_hash_root());
   753→        Ok(execution_payload)
   754→    }
   755→}
