   805→pub fn generate_blobs<E: EthSpec>(
   806→    n_blobs: usize,
   807→    fork_name: ForkName,
   808→) -> Result<(BlobsBundle<E>, Transactions<E>), String> {
   809→    let tx = static_valid_tx::<E>()
   810→        .map_err(|e| format!("error creating valid tx SSZ bytes: {:?}", e))?;
   811→    let transactions = vec![tx; n_blobs];
   812→
   813→    let bundle = if fork_name.fulu_enabled() {
   814→        let (kzg_commitment, kzg_proofs, blob) = load_test_blobs_bundle_v2::<E>()?;
   815→        BlobsBundle {
   816→            commitments: vec![kzg_commitment; n_blobs].into(),
   817→            proofs: vec![kzg_proofs.to_vec(); n_blobs]
   818→                .into_iter()
   819→                .flatten()
   820→                .collect::<Vec<_>>()
   821→                .into(),
   822→            blobs: vec![blob; n_blobs].into(),
   823→        }
   824→    } else {
   825→        let (kzg_commitment, kzg_proof, blob) = load_test_blobs_bundle_v1::<E>()?;
   826→        BlobsBundle {
   827→            commitments: vec![kzg_commitment; n_blobs].into(),
   828→            proofs: vec![kzg_proof; n_blobs].into(),
   829→            blobs: vec![blob; n_blobs].into(),
   830→        }
   831→    };
   832→
   833→    Ok((bundle, transactions.into()))
   834→}
