   920→pub fn generate_genesis_block(
   921→    terminal_total_difficulty: Uint256,
   922→    terminal_block_number: u64,
   923→) -> Result<PoWBlock, String> {
   924→    generate_pow_block(
   925→        terminal_total_difficulty,
   926→        terminal_block_number,
   927→        0,
   928→        ExecutionBlockHash::zero(),
   929→    )
   930→}
   931→
   932→pub fn generate_pow_block(
   933→    terminal_total_difficulty: Uint256,
   934→    terminal_block_number: u64,
   935→    block_number: u64,
   936→    parent_hash: ExecutionBlockHash,
   937→) -> Result<PoWBlock, String> {
   938→    if block_number > terminal_block_number {
   939→        return Err(format!(
   940→            "{} is beyond terminal pow block {}",
   941→            block_number, terminal_block_number
   942→        ));
   943→    }
   944→
   945→    let total_difficulty = if block_number == terminal_block_number {
   946→        terminal_total_difficulty
   947→    } else {
   948→        let increment = terminal_total_difficulty
   949→            .checked_div(Uint256::from(terminal_block_number))
   950→            .expect("terminal block number must be non-zero");
   951→        increment
   952→            .checked_mul(Uint256::from(block_number))
   953→            .expect("overflow computing total difficulty")
   954→    };
   955→
   956→    let mut block = PoWBlock {
   957→        block_number,
   958→        block_hash: ExecutionBlockHash::zero(),
   959→        parent_hash,
   960→        total_difficulty,
   961→        timestamp: block_number,
   962→    };
   963→
   964→    block.block_hash = ExecutionBlockHash::from_root(block.tree_hash_root());
   965→
   966→    Ok(block)
   967→}
