                execution_payload
                    .transactions_mut()
                    .push(tx)
                    .map_err(|_| "transactions are full".to_string())?;
            }
            self.blobs_bundles.insert(id, bundle);
        }

        *execution_payload.block_hash_mut() =
            ExecutionBlockHash::from_root(execution_payload.tree_hash_root());
        Ok(execution_payload)
    }
